import{_ as e,C as o,c as a,o as t,j as r,G as l,a0 as s,b as i,a as n,w as u,a1 as h}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"Goal Setting for Pétanque Players","description":"","frontmatter":{},"headers":[],"relativePath":"en/education/goals/index.md","filePath":"en/education/goals/index.md"}');const g=e({name:"en/education/goals/index.md"},[["render",function(e,c,g,d,p,m){const b=o("AdBanner"),y=o("Mermaid"),f=o("AdInArticle");return t(),a("div",null,[c[1]||(c[1]=r("h1",{id:"goal-setting-for-petanque-players",tabindex:"-1"},[n("Goal Setting for Pétanque Players "),r("a",{class:"header-anchor",href:"#goal-setting-for-petanque-players","aria-label":'Permalink to "Goal Setting for Pétanque Players"'},"​")],-1)),l(b),c[2]||(c[2]=s('<p>Clear goals are your compass. They give direction to your training, motivation when things get hard, and a way to measure progress. Without goals, you&#39;re just throwing boules. With goals, you&#39;re building toward something.</p><div class="tip custom-block"><p class="custom-block-title">The Core Principle</p><p><strong>A goal without a plan is just a wish.</strong> Set clear goals, break them down, focus on what you control, and track your progress.</p></div><h2 id="why-goals-matter" tabindex="-1">Why Goals Matter <a class="header-anchor" href="#why-goals-matter" aria-label="Permalink to &quot;Why Goals Matter&quot;">​</a></h2><p>Goals serve multiple purposes:</p><ul><li><strong>Direction:</strong> Know what to work on</li><li><strong>Motivation:</strong> Have something to strive for</li><li><strong>Measurement:</strong> Track your progress</li><li><strong>Focus:</strong> Prioritize your limited time</li></ul><p>For the self-directed player, goals are especially important. Without a coach pushing you, your goals become your guide.</p><h2 id="the-three-types-of-goals" tabindex="-1">The Three Types of Goals <a class="header-anchor" href="#the-three-types-of-goals" aria-label="Permalink to &quot;The Three Types of Goals&quot;">​</a></h2><p>Not all goals are equal. Understanding the different types helps you set better ones.</p><h3 id="_1-outcome-goals" tabindex="-1">1. Outcome Goals <a class="header-anchor" href="#_1-outcome-goals" aria-label="Permalink to &quot;1. Outcome Goals&quot;">​</a></h3><p><strong>What:</strong> The end result you want <strong>Example:</strong> &quot;Win the regional championship&quot; <strong>Control level:</strong> Low - depends on opponents, conditions, luck</p><h3 id="_2-performance-goals" tabindex="-1">2. Performance Goals <a class="header-anchor" href="#_2-performance-goals" aria-label="Permalink to &quot;2. Performance Goals&quot;">​</a></h3><p><strong>What:</strong> Specific performance standards <strong>Example:</strong> &quot;Achieve 80% accuracy on shooting drills&quot; <strong>Control level:</strong> Medium - depends mostly on you</p><h3 id="_3-process-goals" tabindex="-1">3. Process Goals <a class="header-anchor" href="#_3-process-goals" aria-label="Permalink to &quot;3. Process Goals&quot;">​</a></h3><p><strong>What:</strong> Actions and behaviors you control <strong>Example:</strong> &quot;Complete my pre-shot routine on every throw&quot; <strong>Control level:</strong> High - entirely up to you</p><h3 id="the-goal-hierarchy" tabindex="-1">The Goal Hierarchy <a class="header-anchor" href="#the-goal-hierarchy" aria-label="Permalink to &quot;The Goal Hierarchy&quot;">​</a></h3>',15)),(t(),i(h,null,{default:u(()=>[l(y,{id:"mermaid-71",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BOutcome%20Goal%3Cbr%2F%3EThe%20Dream%5D%20--%3E%20B%5BPerformance%20Goals%3Cbr%2F%3EMilestones%5D%0A%20%20%20%20B%20--%3E%20C%5BProcess%20Goals%3Cbr%2F%3EDaily%20Actions%5D%0A%0A%20%20%20%20A2%5B%22Win%20Regional%20Championship%22%5D%20--%3E%20B2%5B%2280%25%20shooting%20accuracy%22%5D%0A%20%20%20%20B2%20--%3E%20C2%5B%22Complete%20pre-shot%20routine%3Cbr%2F%3Eevery%20throw%22%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e1f5ff%0A%20%20%20%20style%20B%20fill%3A%23fff9c4%0A%20%20%20%20style%20C%20fill%3A%23c8e6c9%0A%20%20%20%20style%20A2%20fill%3A%23e1f5ff%0A%20%20%20%20style%20B2%20fill%3A%23fff9c4%0A%20%20%20%20style%20C2%20fill%3A%23c8e6c9%0A"})]),fallback:u(()=>[...c[0]||(c[0]=[n(" Loading... ",-1)])]),_:1})),c[3]||(c[3]=s('<div class="warning custom-block"><p class="custom-block-title">Key Insight</p><p><strong>Focus most of your attention on process goals.</strong> They&#39;re what you control, and they lead to the outcomes you want.</p><ul><li><strong>Outcome goals:</strong> Low control, high motivation</li><li><strong>Performance goals:</strong> Medium control, measurable progress</li><li><strong>Process goals:</strong> High control, daily focus ← <strong>Focus here</strong></li></ul></div><h2 id="the-smart-framework" tabindex="-1">The SMART Framework <a class="header-anchor" href="#the-smart-framework" aria-label="Permalink to &quot;The SMART Framework&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">SMART Goals Checklist</p><p>Every goal should be:</p><ul><li>✅ <strong>S</strong>pecific - Clear and well-defined</li><li>✅ <strong>M</strong>easurable - You can track progress</li><li>✅ <strong>A</strong>chievable - Challenging but possible</li><li>✅ <strong>R</strong>elevant - Aligned with your bigger picture</li><li>✅ <strong>T</strong>ime-bound - Has a deadline</li></ul></div>',3)),l(f),c[4]||(c[4]=s('<h3 id="s-specific" tabindex="-1">S - Specific <a class="header-anchor" href="#s-specific" aria-label="Permalink to &quot;S - Specific&quot;">​</a></h3><p>❌ &quot;Get better at shooting&quot; ✅ &quot;Improve my au fer (direct hit) accuracy from 8 meters&quot;</p><h3 id="m-measurable" tabindex="-1">M - Measurable <a class="header-anchor" href="#m-measurable" aria-label="Permalink to &quot;M - Measurable&quot;">​</a></h3><p>❌ &quot;Shoot more accurately&quot; ✅ &quot;Score at least 24/30 on the shooting ladder drill&quot;</p><h3 id="a-achievable" tabindex="-1">A - Achievable <a class="header-anchor" href="#a-achievable" aria-label="Permalink to &quot;A - Achievable&quot;">​</a></h3><p>❌ &quot;Never miss a shot&quot; (impossible) ✅ &quot;Improve accuracy by 10% over 8 weeks&quot; (challenging but realistic)</p><h3 id="r-relevant" tabindex="-1">R - Relevant <a class="header-anchor" href="#r-relevant" aria-label="Permalink to &quot;R - Relevant&quot;">​</a></h3><p>❌ &quot;Run a marathon&quot; (not directly related) ✅ &quot;Improve balance and stability for better throwing&quot; (supports your game)</p><h3 id="t-time-bound" tabindex="-1">T - Time-bound <a class="header-anchor" href="#t-time-bound" aria-label="Permalink to &quot;T - Time-bound&quot;">​</a></h3><p>❌ &quot;Someday I&#39;ll be better&quot; ✅ &quot;By March 15th, I will achieve...&quot;</p><h2 id="goal-examples-for-petanque" tabindex="-1">Goal Examples for Pétanque <a class="header-anchor" href="#goal-examples-for-petanque" aria-label="Permalink to &quot;Goal Examples for Pétanque&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Poor Goal</th><th>SMART Goal</th></tr></thead><tbody><tr><td>Outcome</td><td>&quot;Win more&quot;</td><td>&quot;Reach the semi-finals at the Spring Tournament&quot;</td></tr><tr><td>Performance</td><td>&quot;Point better&quot;</td><td>&quot;Achieve 70% of points within 50cm at 8m distance&quot;</td></tr><tr><td>Process</td><td>&quot;Practice more&quot;</td><td>&quot;Complete 3 focused training sessions per week&quot;</td></tr></tbody></table><h2 id="breaking-down-big-goals" tabindex="-1">Breaking Down Big Goals <a class="header-anchor" href="#breaking-down-big-goals" aria-label="Permalink to &quot;Breaking Down Big Goals&quot;">​</a></h2><p>Large goals can feel overwhelming. Break them into smaller pieces:</p><h3 id="example-win-the-club-championship-12-months-away" tabindex="-1">Example: &quot;Win the Club Championship (12 months away)&quot; <a class="header-anchor" href="#example-win-the-club-championship-12-months-away" aria-label="Permalink to &quot;Example: &quot;Win the Club Championship (12 months away)&quot;&quot;">​</a></h3><p><strong>Yearly goal:</strong> Win club championship</p><p><strong>Quarterly goals:</strong></p><ul><li>Q1: Improve shooting accuracy to 75%</li><li>Q2: Develop consistent pre-shot routine</li><li>Q3: Master pressure situations</li><li>Q4: Peak performance and competition prep</li></ul><p><strong>Monthly goals (Q1):</strong></p><ul><li>Month 1: Establish baseline, identify weaknesses</li><li>Month 2: Focus on shooting technique</li><li>Month 3: Add pressure to shooting practice</li></ul><p><strong>Weekly goals (Month 2):</strong></p><ul><li>Week 1: 3 shooting sessions, video analysis</li><li>Week 2: Work on identified technique issue</li><li>Week 3: Increase distance gradually</li><li>Week 4: Test progress, adjust plan</li></ul><h2 id="connecting-goals-to-your-why" tabindex="-1">Connecting Goals to Your &quot;Why&quot; <a class="header-anchor" href="#connecting-goals-to-your-why" aria-label="Permalink to &quot;Connecting Goals to Your &quot;Why&quot;&quot;">​</a></h2><p>Goals work better when connected to deeper motivation.</p><p>Ask yourself:</p><ul><li>Why do I want to achieve this?</li><li>What will it mean to me?</li><li>How will I feel when I succeed?</li><li>What&#39;s driving me to improve?</li></ul><p>Write down your answers. Return to them when motivation fades.</p><h2 id="in-this-section" tabindex="-1">In This Section <a class="header-anchor" href="#in-this-section" aria-label="Permalink to &quot;In This Section&quot;">​</a></h2><ul><li><strong><a href="/en/education/goals/smart-goals">SMART Goals in Detail</a></strong> - Deep dive into creating effective goals</li><li><strong><a href="/en/education/goals/planning">Creating Your Training Plan</a></strong> - Turn goals into action</li></ul><h2 id="summary-goal-setting-rules" tabindex="-1">Summary: Goal Setting Rules <a class="header-anchor" href="#summary-goal-setting-rules" aria-label="Permalink to &quot;Summary: Goal Setting Rules&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Rule #1: The Control Rule</p><p><strong>Focus on process goals (what you control) over outcome goals.</strong> Process goals lead to performance goals, which lead to outcome goals.</p></div><div class="tip custom-block"><p class="custom-block-title">Rule #2: The SMART Rule</p><p><strong>Goals must be Specific, Measurable, Achievable, Relevant, Time-bound.</strong> Vague goals produce vague results. SMART goals produce progress.</p></div><div class="tip custom-block"><p class="custom-block-title">Rule #3: The Breakdown Rule</p><p><strong>Large goals need quarterly, monthly, and weekly milestones.</strong> Break big goals into small, actionable steps you can complete this week.</p></div><div class="tip custom-block"><p class="custom-block-title">Rule #4: The Connection Rule</p><p><strong>Connect goals to your deeper &quot;why.&quot;</strong> When motivation fades, your &quot;why&quot; keeps you going.</p></div><h2 id="key-takeaway" tabindex="-1">Key Takeaway <a class="header-anchor" href="#key-takeaway" aria-label="Permalink to &quot;Key Takeaway&quot;">​</a></h2><blockquote><p>A goal without a plan is just a wish.</p></blockquote><p>Set clear goals. Break them down. Focus on what you control. Track your progress.</p>',37)),l(b)])}]]);export{c as __pageData,g as default};
